export function getSubscriptionCache(nuxtApp: NuxtApp): SubscriptionCache {
  if (!subscriptionRegistry.has(nuxtApp)) {
    subscriptionRegistry.set(nuxtApp, {})
  }
  return subscriptionRegistry.get(nuxtApp)!
